+/* 접이식 상세 필터(종류·상태·섹터·전략). 기본은 접혀 있고 여닫기는 브라우저의 details 가 한다. */
+.details {
+  width: 100%;
+  min-width: 0;
+}
+
+/* summary 는 list-item 그대로 둔다 — display 를 바꾸면 여닫기 표식(::marker)이 사라진다. */
+.details > summary {
+  width: fit-content;
+  color: var(--thorp-copy);
+  font-size: var(--thorp-text-small, 0.78rem);
+  cursor: pointer;
+}
+
+/* classic 은 .filterColumn 이 contents 라 details 안에서 묶음이 붙어 버린다. 바깥 .filters 와 같은 간격으로 흘린다. */
+.details > .filterColumn {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 14px 28px;
+}
+
+/* 상태는 분석·탐색 묶음 한 줄, 경제환경 한 줄이다. 값이 다른 이유가 줄 이름으로 읽힌다. */
+.statusRow {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: center;
+  gap: 6px 12px;
+  width: 100%;
+}
+
+.statusRow > .rowLabel {
+  min-width: 6.5em;
+  color: var(--thorp-muted);
+  font-size: var(--thorp-text-caption, 0.72rem);
+}
+
+/* 묶음 제목 옆의 짧은 안내. 제목보다 한 단 작고 가늘다. */
+.legendHint {
+  margin-left: 6px;
+  color: var(--thorp-muted);
+  font-size: 0.88em;
+  font-weight: 400;
+}
+
+.details > summary:focus-visible {
+  outline: var(--thorp-focus-outline-compact);
+  outline-offset: var(--thorp-focus-offset-compact);
+}
+
+.details[open] > summary {
+  margin-bottom: 12px;
+}
+
+/* 접혀 있어도 그 안에 켜진 것이 있음을 알린다. */
+.count {
+  margin-left: 8px;
+  padding: 1px 8px;
+  border-radius: 999px;
+  color: var(--thorp-foreground);
+  background: var(--thorp-accent-muted);
+  font-size: var(--thorp-text-caption, 0.72rem);
+  font-weight: 600;
+}
+
